// Lightweight zero-dependency syntax highlighter for C, HTML, CSS, JS
window.hljs = {
  highlightAuto: function(code, lang) {
    if (!code) return '';
    let escaped = code
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;');

    // HTML highlighting
    if (lang === 'html' || lang === 'xml') {
      escaped = escaped
        .replace(/(&lt;!--[\s\S]*?--&gt;)/g, '<span class="hljs-comment">$1</span>')
        .replace(/(&lt;\/?)([a-zA-Z0-9\-]+)(.*?)(&gt;)/g, function(match, p1, p2, p3, p4) {
          let attrs = p3.replace(/([a-zA-Z\-:]+)=(".*?"|'.*?'|[^\s>]+)/g, '<span class="hljs-attr">$1</span>=<span class="hljs-string">$2</span>');
          return p1 + '<span class="hljs-tag">' + p2 + '</span>' + attrs + p4;
        });
      return escaped;
    }

    // CSS highlighting
    if (lang === 'css') {
      escaped = escaped
        .replace(/(\/\*[\s\S]*?\*\/)/g, '<span class="hljs-comment">$1</span>')
        .replace(/([^{}]+)\{/g, '<span class="hljs-selector-tag">$1</span>{')
        .replace(/([a-zA-Z\-]+)\s*:/g, '<span class="hljs-attr">$1</span>:')
        .replace(/:\s*([^;]+);/g, ': <span class="hljs-string">$1</span>;');
      return escaped;
    }

    // C, JS, or generic highlighting
    // 1. Strings
    escaped = escaped.replace(/(["'])(?:(?=(\\?))\2[\s\S])*?\1/g, '<span class="hljs-string">$&</span>');
    // 2. Preprocessor directives (C: #include, #define, etc.)
    escaped = escaped.replace(/(#[a-zA-Z_]+(?:\s+&lt;[^&gt;]+&gt;|\s+[^\n]+)?)/g, '<span class="hljs-meta">$1</span>');
    // 3. Comments (// and /* */)
    escaped = escaped.replace(/(\/\/[^\n]*)/g, '<span class="hljs-comment">$1</span>');
    escaped = escaped.replace(/(\/\*[\s\S]*?\*\/)/g, '<span class="hljs-comment">$1</span>');
    // 4. Numbers
    escaped = escaped.replace(/\b(\d+(?:\.\d+)?(?:[eE][+-]?\d+)?|0x[0-9a-fA-F]+)\b/g, '<span class="hljs-number">$1</span>');
    // 5. Keywords
    const keywords = [
      'int','float','double','char','void','long','short','unsigned','signed','const','static','return',
      'if','else','switch','case','default','break','continue','while','do','for','goto','sizeof','struct',
      'typedef','union','enum','function','let','var','const','null','undefined','true','false','bool'
    ];
    const kwRegex = new RegExp('\\b(' + keywords.join('|') + ')\\b', 'g');
    escaped = escaped.replace(kwRegex, '<span class="hljs-keyword">$1</span>');
    // 6. Built-in functions
    const builtins = ['printf','scanf','malloc','free','strlen','strcpy','strcmp','puts','gets','console','log','document','window'];
    const builtinRegex = new RegExp('\\b(' + builtins.join('|') + ')(?=\\s*\\()', 'g');
    escaped = escaped.replace(builtinRegex, '<span class="hljs-built_in">$1</span>');

    return escaped;
  },

  highlightElement: function(el) {
    const lang = el.getAttribute('data-lang') || (el.className.match(/language-([a-z0-9]+)/) || [])[1] || 'c';
    const raw = el.textContent;
    el.innerHTML = this.highlightAuto(raw, lang);
  },

  highlightAll: function() {
    document.querySelectorAll('pre code').forEach(el => this.highlightElement(el));
  }
};
